Hypothesis APART : forall a n sp0 scr0, (forall i, 0 <= i < n -> aclient L ar (PEAEKN.EBX en k ++ (PM.parser_own s ++ LBX)) FF sp0 scr0 (a + i)) -> 0 < n ->
    (a + n <= F \/ F + 128 <= a) /\ (a + n <= F / 8 + SB \/ F / 8 + SB + 16 <= a) /\ (a + n <= fl \/ fl + 1 <= a).
